describe('sanitizeInput', () => {
  it('should escape less-than symbols', () => {
    expect(sanitizeInput('<script>')).toContain('&lt;');
    expect(sanitizeInput('<script>')).not.toContain('<');
  });

  it('should escape greater-than symbols', () => {
    expect(sanitizeInput('alert()>')).toContain('&gt;');
    expect(sanitizeInput('alert()>')).not.toContain('>');
  });

  it('should escape double quotes', () => {
    expect(sanitizeInput('onclick="alert()"')).toContain('&quot;');
    expect(sanitizeInput('onclick="alert()"')).not.toContain('"');
  });

  it('should escape single quotes', () => {
    expect(sanitizeInput("onclick='alert()'")).toContain('&#039;');
    expect(sanitizeInput("onclick='alert()'")).not.toContain("'");
  });

  it('should escape all dangerous characters in complex XSS payload', () => {
    const input = '<img src=x onerror="alert(\'XSS\')"/>';
    const result = sanitizeInput(input);
    expect(result).not.toContain('<');
    expect(result).not.toContain('>');
    expect(result).not.toContain('"');
    expect(result).toContain('&lt;');
    expect(result).toContain('&gt;');
    expect(result).toContain('&quot;');
  });

  it('should handle empty string', () => {
    expect(sanitizeInput('')).toBe('');
  });

  it('should handle strings without dangerous characters', () => {
    expect(sanitizeInput('Normal text 123')).toBe('Normal text 123');
  });
});

