    const input = { title: 'a'.repeat(201), description: 'desc' };

    await expect(createTodo(input)).rejects.toThrow('Invalid todo input');
  });

  it('should handle database errors gracefully', async () => {
    jest.spyOn(db, 'query').mockRejectedValue(new Error('DB Connection failed'));
    const input = { title: 'Valid', description: 'desc' };

    await expect(createTodo(input)).rejects.toThrow('DB Connection failed');
  });

  it('should use parameterized query to prevent SQL injection', async () => {
    const mockQuery = jest.spyOn(db, 'query').mockResolvedValue([]);
    const input = { title: "'; DROP TABLE todos; --", description: 'desc' };

    await createTodo(input);

    // Verify parameterized query was used
