describe('sanitizeInput - Edge Cases', () => {
  it('should handle multiple consecutive dangerous characters', () => {
    const input = '<<<>>>""\'\'\'';
    const result = sanitizeInput(input);
    expect(result).toBe('&lt;&lt;&lt;&gt;&gt;&gt;&quot;&quot;&quot;&#039;&#039;&#039;');
  });

  it('should handle mixed HTML and attributes', () => {
    const input = '<div class="test" id=\'myid\'>';
    const result = sanitizeInput(input);
    expect(result).not.toMatch(/[<>"']/); // No unescaped characters
  });

  it('should not double-escape already escaped content', () => {
    // Important: sanitize should not be idempotent for already-escaped content
    const input = '&lt;script&gt;';
    const result = sanitizeInput(input);
    // The & in &lt; will be preserved as-is (function doesn't escape &)
    expect(result).toBe('&lt;script&gt;');
  });
});

