const VALIDATION_RULES: ValidationRule[] = [
  {
    validate: (input) => input.title?.trim().length > 0,
    message: 'Title cannot be empty'
  },
  {
    validate: (input) => input.title.length <= 200,
    message: 'Title must be 200 characters or less'
  },
  {
    validate: (input) => !input.description || input.description.length <= 1000,
    message: 'Description must be 1000 characters or less'
  }
];

export function validateTodoInput(input: CreateTodoInput): { valid: boolean; errors: string[] } {
  const errors = VALIDATION_RULES
    .filter(rule => !rule.validate(input))
    .map(rule => rule.message);
  return { valid: errors.length === 0, errors };
}

